Here's a complete email-password auth system with hashing, sessions, and rate limiting:

**server.js**
```javascript
import express from 'express';
import Database from 'better-sqlite3';
import bcrypt from 'bcrypt';
import crypto from 'crypto';

const app = express();
app.use(express.json());

// SQLite setup
const db = new Database('/tmp/auth.db');
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    created_at INTEGER
  );
  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    created_at INTEGER,
    expires_at INTEGER,
    FOREIGN KEY(user_id) REFERENCES users(id)
  );
  CREATE TABLE IF NOT EXISTS login_attempts (
    email TEXT NOT NULL,
    timestamp INTEGER,
    PRIMARY KEY(email, timestamp)
  );
`);

const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_ATTEMPTS = 5;
const SESSION_DURATION = 7 * 24 * 60 * 60 * 1000; // 7 days

// Check rate limit
function checkRateLimit(email) {
  const cutoff = Date.now() - RATE_LIMIT_WINDOW;
  const attempts = db.prepare(
    'SELECT COUNT(*) as count FROM login_attempts WHERE email = ? AND timestamp > ?'
  ).get(email, cutoff);

  return attempts.count < MAX_ATTEMPTS;
}

// Record failed attempt
function recordFailedAttempt(email) {
  db.prepare('INSERT INTO login_attempts (email, timestamp) VALUES (?, ?)')
    .run(email, Date.now());
}

// Clear old attempts
function clearOldAttempts(email) {
  const cutoff = Date.now() - RATE_LIMIT_WINDOW;
  db.prepare('DELETE FROM login_attempts WHERE email = ? AND timestamp <= ?')
    .run(email, cutoff);
}

// Generate session
function createSession(userId) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const expiresAt = Date.now() + SESSION_DURATION;
  db.prepare('INSERT INTO sessions (id, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)')
    .run(sessionId, userId, Date.now(), expiresAt);
  return sessionId;
}

// Verify session
function verifySession(sessionId) {
  const session = db.prepare('SELECT * FROM sessions WHERE id = ? AND expires_at > ?')
    .get(sessionId, Date.now());
  return session;
}

app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password || password.length < 8) {
    return res.status(400).json({ error: 'Invalid email or password (min 8 chars)' });
  }

  try {
    const hash = await bcrypt.hash(password, 10);
    db.prepare('INSERT INTO users (email, password_hash, created_at) VALUES (?, ?, ?)')
      .run(email, hash, Date.now());

    const user = db.prepare('SELECT id FROM users WHERE email = ?').get(email);
    const sessionId = createSession(user.id);
    res.json({ sessionId, userId: user.id });
  } catch (err) {
    if (err.message.includes('UNIQUE')) {
      res.status(409).json({ error: 'Email already exists' });
    } else {
      res.status(500).json({ error: 'Signup failed' });
    }
  }
});

app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  if (!checkRateLimit(email)) {
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }

  const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);

  if (!user || !(await bcrypt.compare(password, user.password_hash))) {
    recordFailedAttempt(email);
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  clearOldAttempts(email);
  const sessionId = createSession(user.id);
  res.json({ sessionId, userId: user.id });
});

app.get('/me', (req, res) => {
  const sessionId = req.headers.authorization?.split(' ')[1];

  if (!sessionId) {
    return res.status(401).json({ error: 'No session' });
  }

  const session = verifySession(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }

  const user = db.prepare('SELECT id, email FROM users WHERE id = ?').get(session.user_id);
  res.json(user);
});

app.post('/logout', (req, res) => {
  const sessionId = req.headers.authorization?.split(' ')[1];
  if (sessionId) {
    db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
  }
  res.json({ ok: true });
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

**Key features:**
- **Hashing:** `bcrypt` with 10 salt rounds
- **Sessions:** Crypto-random 32-byte tokens, 7-day expiry
- **Rate limit:** 5 failed attempts per email in 15-min window; blocks further attempts
- **DB:** SQLite with users, sessions, login_attempts tables
- **Endpoints:** `/signup`, `/login`, `/me`, `/logout`

**Install & run:**
```bash
npm install
npm start
```

**Test:**
```bash
# Signup
curl -X POST http://localhost:3000/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"password123"}'

# Login
curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"password123"}'

# Check auth (paste returned sessionId)
curl http://localhost:3000/me \
  -H "Authorization: Bearer <sessionId>"
```

To use: copy server.js and package.json, run `npm install && npm start`. DB auto-creates at `/tmp/auth.db`.
